/// Reboot. Cost 0, Exhaust. Move hand into draw, then shuffle (which in
/// C# also merges the discard pile in) and draw CardsVar (4 base / 6
/// upgraded). C# `Reboot.cs`: `foreach (item in Hand.Cards) CardPileCmd
/// .Add(item, Draw); await CardPileCmd.Shuffle(...); await CardPileCmd
/// .Draw(...)`. `CardPileCmd.Shuffle` (`CardPileCmd.cs:804`) pulls the
/// discard pile into draw before the StableShuffle, so the net effect IS
/// hand+draw+discard → draw (verified against the C# headless harness:
/// discarded cards are drawn back). Bead `sts2-rs-s2pr8` corrected the
/// earlier `p5lg5` note, which wrongly read `CardPileCmd.Shuffle` as a
/// draw-pile-only shuffle and dropped the discard merge.
/// `state.shuffle_draw_pile()` now models `CardPileCmd.Shuffle` faithfully
/// (discard-merge + `(Entry, upgrade)` StableShuffle pre-sort).
pub(crate) fn play_reboot(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let hand_uids: smallvec::SmallVec<[sts2_core::CardUid; 16]> =
        state.player.hand.drain(..).collect();
    for uid in hand_uids {
        state.player.draw.push(uid);
    }
    state.shuffle_draw_pile();
    // C# `Reboot.cs` `CardsVar(4)` with `OnUpgrade UpgradeValueBy(2m)`
    // → draw 4 base / draw 6 upgraded.
    let draws = if current_card_upgraded(state) { 6 } else { 4 };
    let _ = sts2_core::cards::draw_via_state(state, draws);
    EffectResult::Resolved
}

